$dir1 = "C:\Users\renu5\OneDrive\Pictures\Camera imports"
$dir2 = "C:\All phones data"

Write-Output "Fetching files..."
$files1 = Get-ChildItem -Path $dir1 -File -Recurse -ErrorAction SilentlyContinue
$files2 = Get-ChildItem -Path $dir2 -File -Recurse -ErrorAction SilentlyContinue

$f2Names = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
foreach ($f in $files2) {
    $f2Names.Add($f.Name) > $null
}

# For fuzzy matching, let's also keep an array
$f2NameArray = [string[]]($f2Names)

$overlaps = [System.Collections.Generic.List[string]]::new()

