        # For very short names, only do exact match
        if ($f2Names.Contains($f1.Name)) {
            $overlaps.Add($f1.FullName)
        }
        continue 
    }

    $found = $false
    foreach ($n2 in $f2NameArray) {
        if ($n2.IndexOf($base1, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
            $found = $true
            break
        }
    }
    if ($found) {
        $overlaps.Add($f1.FullName)
    }
}

Write-Output "Found $($overlaps.Count) overlapping files using fuzzy name matching."
$overlaps | Out-File -FilePath "$env:TEMP\overlapping_files_fuzzy.txt" -Encoding UTF8
Write-Output "Saved to $env:TEMP\overlapping_files_fuzzy.txt"

